function qmCollectAlbums(node, out, seen, depth) {
  var ctx = this;
  if (node == null || depth > 8) return;
  if (Object.prototype.toString.call(node) === '[object Array]') {
    for (var i = 0; i < node.length; i++) {
      qmCollectAlbums.call(ctx, node[i], out, seen, depth + 1)
    }
    return
  }
  if (typeof node != 'object') return;
  var aid = String(node.album_id || '');
  if (aid && aid != '0' && (node.title || node.original_title)) {
    if (!seen[aid]) {
      seen[aid] = 1;
      out.push({
        album_id: aid,
        title: node.title || node.original_title || '',
        cover: node.image_link || '',
        intro: node.intro || '',
        author: node.author || node.original_author || '',
        kind: node.sub_title || node.ptags || '',
        last_chapter: (node.is_over == '1' ? '已完结' : '连载中'),
        url: qmAlbumDetailUrl.call(ctx, aid)
      })
    }
  }
  var ks = Object.keys(node);
  for (var j = 0; j < ks.length; j++) {
    var k = ks[j];
    if (/^(meta|stat_params|track_id|tag_items|category_list|rank_list|share|attribute|comment_detail|filters|sections|section_header|rank_items)$/.test(k)) continue;
    qmCollectAlbums.call(ctx, node[k], out, seen, depth + 1)
  }
}

function qmParseAlbumList(t) {
  var ctx = this;
  var d = qmParse(t).data || {};
  var r = [];
  if (d.books && Object.prototype.toString.call(d.books) === '[object Array]') {
    for (var i = 0; i < d.books.length; i++) {
      var x = d.books[i] || {};
      var aid = String(x.album_id || x.id || '');
      if (!aid || !x.title) continue;
      r.push({
        album_id: aid,
        title: x.title || x.original_title || '',
        cover: x.image_link || '',
        intro: x.intro || '',
        author: x.author || x.original_author || '',
        kind: x.sub_title || x.ptags || '',
        last_chapter: (x.is_over == '1' ? '已完结' : '连载中'),
        url: qmAlbumDetailUrl.call(ctx, aid)
      })
    }
  } else {
    var l = [],
      s = {};
    qmCollectAlbums.call(ctx, d, l, s, 0);
    r = l
  }
  return JSON.stringify({
    data: r
  })
}

function qmBuildAlbumInfoText(d, voices, cfg, albumId) {
  var book = d.book || {};
  var parts = [];
  parts.push('✍️ 作者：' + String(book.author || ''));
  parts.push('📊 状态：' + (String(book.is_over) === '1' ? '✅ 已完结' : '📖 连载中'));
  if (book.chapter_list_desc) parts.push('📚 进度：' + book.chapter_list_desc);
  if (book.update_time_desc) parts.push('🕐 更新：' + book.update_time_desc);
  var tags = [];
  (book.book_tag_list || []).forEach(function(t){ if (t && t.title) tags.push(String(t.title)); });
  if (tags.length) parts.push('🏷️ 标签：' + tags.join(' / '));
  var realVoices = voices.filter(function(v){ return String(v.voice_type) == '3' && v.voice_name; });
  var aiVoices = voices.filter(function(v){
    if (String(v.voice_id) === '200') return false;
    return (String(v.voice_type) == '5' || String(v.voice_type) == '9') && v.voice_id;
  });
  if (realVoices.length) {
    parts.push('');
    parts.push('🎙️ 真人音源');
    realVoices.forEach(function(v){
      var names = String(v.voice_name || '').split(',').map(function(s){ return s.trim(); }).filter(function(s){ return !!s; });
      if (names.length) parts.push('  • ' + names.join(' / '));
    });
  }
  if (aiVoices.length) {
    parts.push('');
    parts.push('🎛️ AI音色（美化模式下可点击按钮选择；也可到「更多设置 → 设置书籍变量」填 ID）');
    aiVoices.forEach(function(v){
      var vid = String(v.voice_id || '');
      var cur = (vid === String(cfg)) ? ' ←当前' : '';
      var rec = (vid === '10') ? ' ⭐' : '';
      parts.push('  [' + vid + '] ' + (v.voice_name || '') + rec + cur);
    });
  }
  if (cfg) {
    var found = false;
    for (var i = 0; i < voices.length; i++) {
      if (String(voices[i].voice_id) === String(cfg)) { found = true; break; }
    }
    parts.push('');
    if (found) parts.push('✅ 当前音色ID：' + cfg);
    else parts.push('⚠️ 本书不支持音色ID「' + cfg + '」，请修改书籍变量');
  } else if (realVoices.length) {
    parts.push('');
    parts.push('ℹ️ 未设置音色ID，将使用真人音源');
  } else if (aiVoices.length) {
    parts.push('');
    parts.push('ℹ️ 未设置音色ID，将自动使用 AI 音色');
  }
  if (book.intro) {
    parts.push('');
    parts.push('【简介】');
    parts.push(book.intro);
  }
  return parts.join('\n');
}

