  return null
}

function qmC_SourceOf() {
  try {
    if (this && this.source) return this.source
  } catch (e) {}
  try {
    if (typeof source != 'undefined' && source) return source
  } catch (e2) {}
  return null
}

function qmC_Map(v, from, to) {
  var out = '';
  v = String(v);
  for (var i = 0; i < v.length; i++) {
    var idx = from.indexOf(v.charAt(i));
    out += idx >= 0 ? to.charAt(idx) : v.charAt(i)
  }
  return out
}

function qmC_ParamEncode(value) {
  var j = qmC_JavaOf.call(this);
  var b64 = String(j.base64Encode(String(value))).replace(/[=\r\n]/g, '');
  return qmC_Map(b64, QM_C_B64, QM_C_PMAP)
}

function qmC_RandomHex(length) {
  var j = qmC_JavaOf.call(this);
  var v = String(j.randomUUID()).replace(/-/g, '');
  while (v.length < length) v += String(j.randomUUID()).replace(/-/g, '');
  return v.slice(0, length)
}

function qmC_Pad(v, len) {
  v = String(v);
  while (v.length < len) v = '0' + v;
  return v
}

function qmC_Day() {
  var d = new Date();
  return d.getFullYear() + qmC_Pad(d.getMonth() + 1, 2) + qmC_Pad(d.getDate(), 2)
}

function qmC_DateStamp() {
  var d = new Date();
  return d.getFullYear() + qmC_Pad(d.getMonth() + 1, 2) + qmC_Pad(d.getDate(), 2) + qmC_Pad(d.getHours(), 2) + qmC_Pad(d.getMinutes(), 2) + qmC_Pad(d.getSeconds(), 2)
}

function qmC_Sign(value) {
  return String(qmC_JavaOf.call(this).md5Encode(String(value) + QM_C_SECRET))
}

function qmC_UrlSign(data) {
  var keys = Object.keys(data || {}).sort();
  var text = '';
  keys.forEach(function(k) {
    text += k + '=' + String(data[k])
  });
  return qmC_Sign.call(this, text)
}

function qmC_Form(data) {
  return Object.keys(data || {}).sort().map(function(k) {
    return encodeURIComponent(k) + '=' + encodeURIComponent(String(data[k]))
  }).join('&')
}

function qmC_Device() {
