  ];
  var parts = fields.map(function(f) {
    return JSON.stringify(f[0]) + ':' + JSON.stringify(String(f[1]))
  });
  return qmC_ParamEncode.call(this, '{' + parts.join(',') + '}')
}

function qmC_HeaderSign(token, qp) {
  var values = {
    'AUTHORIZATION': token || '',
    'app-version': QM_C_APPV,
    'application-id': QM_C_APPID,
    'channel': QM_C_CHANNEL,
    'is-white': '0',
    'net-env': '1',
