function qmC_Login() {
  var src = qmC_SourceOf.call(this);
  var token = String(src.get('qm_c_token') || '');
  var exp = Number(src.get('qm_c_exp') || 0);
  if (token && exp > Math.floor(Date.now() / 1000) + 60) return token;
  try {
    var form = {
      cancell_check: '1',
      gender: '0'
    };
    form.sign = qmC_UrlSign.call(this, form);
    var headers = qmC_Headers.call(this, '');
    headers['content-type'] = 'application/x-www-form-urlencoded';
    var option = {
      method: 'POST',
      headers: headers,
      body: qmC_Form(form)
    };
    var resp = JSON.parse(String(qmC_JavaOf.call(this).ajax('https://xiaoshuo.wtzw.com/api/v1/login/tourist,' + JSON.stringify(option)) || '{}'));
    token = String((resp && resp.data && resp.data.token) || '');
    if (!token) return '';
    src.put('qm_c_token', token);
    src.put('qm_c_exp', String(Math.floor(Date.now() / 1000) + 3600))
  } catch (e) {
    return ''
  }
  return token
}

function qmC_Request(method, url, params, form) {
  var j = qmC_JavaOf.call(this);
  var token = qmC_Login.call(this);
  var option = {
    method: method,
    headers: qmC_Headers.call(this, token)
  };
  if (form) {
    var body = {};
    Object.keys(form || {}).forEach(function(k) {
      body[k] = String(form[k])
    });
    body.sign = qmC_UrlSign.call(this, body);
    option.headers['content-type'] = 'application/x-www-form-urlencoded';
    option.body = qmC_Form(body)
  } else {
    var query = {};
    Object.keys(params || {}).forEach(function(k) {
      query[k] = String(params[k])
    });
    var parts = Object.keys(query).sort().map(function(k) {
      return encodeURIComponent(k) + '=' + encodeURIComponent(query[k])
    });
    parts.push('sign=' + qmC_UrlSign.call(this, query));
    url += '?' + parts.join('&')
  }
  return JSON.parse(String(j.ajax(url + ',' + JSON.stringify(option)) || '{}'))
}

function qmC_Get(url, params) {
  return qmC_Request.call(this, 'GET', url, params, null)
}

function qmC_PostForm(url, form) {
  return qmC_Request.call(this, 'POST', url, {}, form)
}

function qmC_Esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}

