function qmUniqueComments(list) {
  var seen = {};
  return list.filter(function(x) {
    var key = x.id || (x.name + x.content);
    if (seen[key]) return false;
    seen[key] = 1;
    return true
  })
}

function qmCommentPageData(input) {
  try {
    input = input || {};
    var ctx = this;
    var cur = String(input.cursor || '');
    var response, data, list = [],
      tags = [],
      total = '',
      next = '';
    var rate = {
      score: '',
      count: '',
      positive: '',
      normal: '',
      negative: ''
    };
    var bid = String(input.bookId || '');
    var bh = String(input.hot || '0') == '1';
    var bp = {
      book_id: bid,
      tag_id: String(input.tag || '1'),
      sort: bh ? '0' : '1',
      source: '1',
      audio_type: '3'
    };
    if (cur) bp.next_id = cur;
    response = qmC_Get.call(ctx, 'https://api-cmnt.wtzw.com/api/v1/comment/book-evaluates', bp);
    data = (response && response.data) || {};
    list = (data.comment_list || []).map(function(x) {
      return qmCommentItem.call(ctx, x, bh)
    });
    if (!cur && list.length === 0) {
      bp.audio_type = '1';
      response = qmC_Get.call(ctx, 'https://api-cmnt.wtzw.com/api/v1/comment/book-evaluates', bp);
      data = (response && response.data) || {};
      list = (data.comment_list || []).map(function(x) {
        return qmCommentItem.call(ctx, x, bh)
      })
    }
    if (!cur) {
      total = String(data.eval_comment_count || data.eval_people_count || list.length);
      rate.score = String((data.book && data.book.score) || '');
      var pc = String(data.eval_people_count || '');
      if (pc && !/人|评价/.test(pc)) pc = pc + '人评价';
      rate.count = pc;
      rate.positive = String(data.positive_percent || '');
      rate.normal = String(data.normal_percent || '');
      rate.negative = String(data.negative_percent || '')
    }
    next = String(data.next_id || '');
    tags = (data.tag_list || []).map(function(x) {
      return {
        id: String(x.id || x.tag_id || '1'),
        title: String(x.name || x.title || '全部'),
        count: String(x.count || '')
      }
    });
    return JSON.stringify({
      ok: true,
      kind: 'book',
      items: qmUniqueComments(list),
      next: next,
      total: total,
      tags: tags,
      rate: rate
    })
  } catch (e) {
    return JSON.stringify({
      ok: false,
      error: String(e && e.message || e),
      items: [],
      next: '',
      rate: {}
    })
  }
}

function qmReplyPageData(input) {
  try {
    input = input || {};
    var ctx = this;
    var cur = String(input.cursor || '');
    var cid = String(input.commentId || '');
    var bid = String(input.bookId || '');
    var response = qmC_Get.call(ctx, 'https://api-cmnt.wtzw.com/api/v1/comment/detail', {
      comment_id: cid,
      book_id: bid,
      next_id: cur,
      chapter_id: '',
      from: ''
    });
    var data = (response && response.data) || {};
    var list = qmUniqueComments((data.reply_list || data.comment_list || []).map(function(x) {
      return qmCommentItem.call(ctx, x, false)
    }));
    var next = String(data.next_id || '');
    if (next && next == cur) next = '';
    return JSON.stringify({
      ok: true,
      items: list,
      next: next
    })
  } catch (e) {
    return JSON.stringify({
      ok: false,
      error: String(e && e.message || e),
      items: [],
      next: ''
    })
  }
}

function qmEmojiData(input) {
  input = input || {};
  var tokens = input.tokens || [];
  if (!Array.isArray(tokens)) tokens = [tokens];
  var result = {};
  tokens.slice(0, 6).forEach(function(token) {
    token = String(token || '');
    if (typeof QM_EMOJI_DATA !== 'undefined' && QM_EMOJI_DATA[token]) result[token] = QM_EMOJI_DATA[token]
  });
  return JSON.stringify(result)
}

