function qmOpenComment(kind, bid, cid, pid, heading, checkId, paragraphText, bookName, bookCover) {
  var bk = null;
  try {
    bk = (this && this.book) ? this.book : (typeof book !== 'undefined' ? book : null)
  } catch (e) {}
  if (!bookCover && bk && bk.coverUrl) bookCover = String(bk.coverUrl);
  if (!bookName && bk && bk.name) bookName = String(bk.name);
  var html = qmCommentHtml.call(this, kind, bid, cid, pid, heading, checkId, paragraphText, bookName, bookCover);
  var j = qmC_JavaOf.call(this);
  if (!j || typeof j.showBrowser !== 'function') return false;
  var hp = 0.88,
    cr = 16;
  try {
    var src = qmSourceOf.call(this);
    var h = src.get('qm_comment_height');
    if (h && String(h).trim() !== '') {
      var hv = Number(String(h).replace(/[^\d.\-]/g, ''));
      if (isFinite(hv) && hv > 0) hp = hv > 1 ? hv / 100 : hv;
      if (hp <= 0 || hp > 1) hp = 0.88
    }
    var r = src.get('qm_comment_radius');
    if (r && String(r).trim() !== '') {
      var rv = parseInt(String(r).replace(/[^\d\-]/g, ''), 10);
      if (isFinite(rv) && rv >= 0) cr = Math.min(50, rv)
    }
  } catch (e3) {}
  j.showBrowser('https://api-cmnt.wtzw.com/', html, 'window.java=java;window.source=source;window.qmRun=run;', JSON.stringify({
    state: 4,
    isHideable: true,
    heightPercentage: hp,
    widthPercentage: 1.0,
    dismissOnTouchOutside: true,
    skipCollapsed: true,
    expandedCornersRadius: cr,
    isGestureInsetBottomIgnored: true,
    hardwareAccelerated: true,
    webViewInitialScale: 100
  }));
  return true
}

function qmOpenBookReview(bid, title) {
  return qmOpenComment.call(this, 'book', String(bid || ''), '', '', '七猫书评', '', '', String(title || ''), '')
}

