@js:
var albumId = qmUrlValue(baseUrl, 'album_id');
var chapterId = qmUrlValue(baseUrl, 'chapter_id');
var s = qmSourceOf(this);
var captionUrl = '';
var usedVoice = '';

try {
  if (s) {
    captionUrl = String(s.get('qm_caption_' + albumId + '_' + chapterId) || '');
    usedVoice = String(s.get('qm_used_voice_' + albumId + '_' + chapterId) || '');
  }
} catch (e) {}

if (!usedVoice) {
  var cfg0 = qmGetVoiceId.call(this, albumId);
  if (cfg0) usedVoice = cfg0;
}

if (!captionUrl) {
  try {
    var j = qmJavaOf(this);
    var captionResp = qmParse(j.ajax(qmCaptionListUrl.call(this, albumId, chapterId)));
    var captionList = (captionResp.data && (captionResp.data.list || captionResp.data.chapter_list)) || [];
    var matched = '';
    var fallback = '';
    for (var ci = 0; ci < captionList.length; ci++) {
      var cit = captionList[ci] || {};
      if (String(cit.chapter_id) !== String(chapterId)) continue;
      if (!fallback) fallback = String(cit.caption_url || '');
      if (usedVoice && String(cit.voice_id) === String(usedVoice)) {
        matched = String(cit.caption_url || '');
        break;
      }
    }
    captionUrl = matched || fallback;
    if (captionUrl && s) s.put('qm_caption_' + albumId + '_' + chapterId, captionUrl);
  } catch (e2) {}
}

if (!captionUrl) {
  try {
    var j2 = qmJavaOf(this);
    var info = qmParse(j2.ajax(qmAlbumInfoUrl.call(this, albumId, chapterId)));
    var bookId = String((info.data && info.data.book && info.data.book.id) || '');
    if (bookId) {
      var novelResp = qmParse(j2.ajax(qmNovelChapterListUrl.call(this, bookId)));
      var novelList = (novelResp.data && (novelResp.data.chapter_lists || novelResp.data.chapter_list || novelResp.data.list || novelResp.data.chapters)) || [];
      var tocResp = qmParse(j2.ajax(qmAlbumTocUrl.call(this, albumId)));
      var audioList = (tocResp.data && (tocResp.data.chapter_list || tocResp.data.chapter_lists || tocResp.data.list || tocResp.data.chapters)) || [];
      var curIndex = '';
      for (var i = 0; i < audioList.length; i++) {
        if (String(audioList[i].id) === String(chapterId)) {
          curIndex = String(audioList[i].index || '');
          break;
        }
      }
      var novelId = '';
      var contentMd5 = '';
      for (var n = 0; n < novelList.length; n++) {
        if (String(novelList[n].id) === String(chapterId)) {
          novelId = String(novelList[n].id);
          contentMd5 = String(novelList[n].content_md5 || '');
          break;
        }
      }
      if (!novelId && curIndex) {
        for (var m = 0; m < novelList.length; m++) {
          if (String(novelList[m].index || '') === curIndex) {
            novelId = String(novelList[m].id);
            contentMd5 = String(novelList[m].content_md5 || '');
            break;
          }
        }
      }
      if (!novelId) {
        novelId = String(chapterId);
        contentMd5 = '';
      }
      if (novelId && contentMd5) {
        var preloadResp = qmParse(j2.ajax(qmPreloadUrl.call(this, bookId, novelId, contentMd5, usedVoice || '8')));
        var preloadList = (preloadResp.data && (preloadResp.data.chapter_list || preloadResp.data.list)) || [];
        if (preloadList.length && preloadList[0].caption_url) {
          captionUrl = String(preloadList[0].caption_url);
          if (s) s.put('qm_caption_' + albumId + '_' + chapterId, captionUrl);
        }
      }
    }
  } catch (e3) {}
}

if (!captionUrl) {
  result = '';
} else {
  try {
    var text = java.ajax(captionUrl);
    var captions = JSON.parse(text);
    result = qmCaptionToLrc(captions);
  } catch (e4) {
    result = '';
  }
}

